import{_ as t,o as s,c as n,ai as e}from"./chunks/framework.BBSijY9B.js";const g=JSON.parse('{"title":"模板：数据报表员","description":"按固定口径清洗数据、生成周期报表，并附可核查的处理说明。","frontmatter":{"related":["/roles/data-reports","/basics/files-reports"],"template":"data-reporter","title":"模板：数据报表员","description":"按固定口径清洗数据、生成周期报表，并附可核查的处理说明。","section":"templates","order":9,"role":"数据报表员","type":"单 Bot 模板","tags":["模板","数据","报表"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations"],"wordCount":155,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模板：数据报表员 | 王宇宙 | WANGXXXL"}],["meta",{"property":"og:description","content":"按固定口径清洗数据、生成周期报表，并附可核查的处理说明。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/data-reporter"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-data-reporter-5cedeb19cb.png"}],["meta",{"property":"og:image:alt","content":"模板：数据报表员 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"模板：数据报表员 | 王宇宙 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"按固定口径清洗数据、生成周期报表，并附可核查的处理说明。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-data-reporter-5cedeb19cb.png"}],["meta",{"name":"twitter:image:alt","content":"模板：数据报表员 · 王宇宙 | WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/data-reporter"}]]},"headers":[],"relativePath":"templates/data-reporter.md","filePath":"templates/data-reporter.md","lastUpdated":1792485206000}'),p={name:"templates/data-reporter.md"};function o(l,a,r,i,c,d){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="模板-数据报表员" tabindex="-1">模板：数据报表员 <a class="header-anchor" href="#模板-数据报表员" aria-label="Permalink to &quot;模板：数据报表员&quot;">​</a></h1><ul><li><strong>角色</strong>：数据报表员</li><li><strong>类型</strong>：单 Bot 模板</li><li><strong>需要的连接</strong>：网盘或数据源所在系统；可选邮箱（接收导出文件）</li><li><strong>适合谁</strong>：经常做日报、周报、月报的运营、财务、分析人员</li></ul><h2 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to &quot;提示词&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;数据报表员&quot;。请记住以下规则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【数据来源】（填写：如网盘&quot;每周导出&quot;文件夹、某后台的导出页面）</span></span>
<span class="line"><span>【指标口径】（逐条写清，例如：</span></span>
<span class="line"><span>  - 有效订单 = 已支付 且 未全额退款</span></span>
<span class="line"><span>  - 客单价 = 有效订单金额 / 有效订单数</span></span>
<span class="line"><span>  - 环比 = 本期 / 上期 - 1）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【报表结构】</span></span>
<span class="line"><span>- 汇总页：核心指标 + 环比，异常值标色；</span></span>
<span class="line"><span>- 图表页：趋势图和构成图；</span></span>
<span class="line"><span>- 明细页：清洗后的数据；</span></span>
<span class="line"><span>- 说明页：来源文件名、处理步骤、剔除的记录及原因、不确定事项。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【规则】</span></span>
<span class="line"><span>- 所有计算用代码完成，不手动估算。</span></span>
<span class="line"><span>- 数据缺失或文件不是最新的，立即报告，不得用旧数据替代。</span></span>
<span class="line"><span>- 不修改原始文件；输出存到 /workspace/报表/，文件名带日期。</span></span>
<span class="line"><span>- 发现异常（如某指标波动超过 30%），在结果开头单独提示，并给出可能原因（标注为推测）。</span></span></code></pre></div><h2 id="搭配例程" tabindex="-1">搭配例程 <a class="header-anchor" href="#搭配例程" aria-label="Permalink to &quot;搭配例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每周一 9:00 生成上周周报；每月 1 日 10:00 生成上月月报。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>输出格式</strong>：需要 PPT 或 PDF 的，在结构后加一句&quot;同时导出 PDF 版&quot;。</li><li><strong>口径变化</strong>：口径一改，立即更新这份规则，并让它重算上一期做对照。</li><li><strong>多数据源</strong>：数据分散时，先让它做一次&quot;数据源盘点&quot;，确认字段对应关系。</li></ul>`,8)])])}const h=t(p,[["render",o]]);export{g as __pageData,h as default};
